#include<bits/stdc++.h>

using namespace std;

class DaySo{
	private:
		int n;
		int *a;
	public:
		DaySo(){
		    n = 0;
        	a = new int[50];
		}
	    int getN() { 
	        return n; 
	    }
		int* getA() {
		    return a;
		}
		int& operator[](int index) {
		    if (index >= 0 && index < n) {
		        return a[index]; // Nếu hợp lệ thì trả về phần tử
		    }
		    // Trường hợp không hợp lệ, trả về phần tử đầu tiên để tránh lỗi crash chương trình
		    cout << "Chi so khong hop le!" << endl;
		    return a[0]; 
		}
		friend istream& operator >> (istream &is, DaySo &ds){
			cout << "\nNhap so phan tu: ";
			is >> ds.n;
			cout << endl;
			for(int i = 0; i < ds.n; i++){
				cout << "Nhap he so cua phan tu " << i << ": ";
				is >> ds[i];
			}
	        cout << endl;
	        return is;
		}
		friend ostream& operator << (ostream &os, const DaySo &ds){
			os << "\n--Gia tri day so luu duoc--" << endl;
			for(int i = 0; i < ds.n; i++){
				os << "Phan tu " << i << ": ";
				os << ds.a[i] << endl;
			}
	        os << endl;
	        return os;
		}
};

int tongDuong(DaySo &ds) {
    int tong = 0; 
    for (int i = 0; i < ds.getN(); i++) { 
        if (ds[i] > 0) {
            tong += ds[i];
        }
    }
    return tong;
}

int maxChan(DaySo &ds) {
    int tmp = 0; 
    for (int i = 0; i < ds.getN(); i++) { 
        if ((ds[i] > tmp) && (ds[i] % 2 == 0)) {
            tmp = ds[i];
        }
    }
    return tmp;
}


int main(){
	DaySo A;
	cout << "=== NHAP DU LIEU DAY SO A ===" << endl;
	cin >> A;
	cout << "=== XUAT DU LIEU DAY SO A ===" << endl;
	cout << A;
	cout << "=== KET QUA TINH TOAN ===" << endl;
	cout << "Tong cac phan tu duong: " << tongDuong(A) << endl;
	int max_chan = maxChan(A);
	if (max_chan != 0) {
		cout << "Phan tu chan lon nhat: " << max_chan << endl;
	} else {
		cout << "Day so khong co so chan duong!" << endl;
	}
	return 0;
}

